package com.instaclone.controller;
import com.instaclone.model.User; import com.instaclone.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*;
@Controller public class AuthController { final UserRepository repo; final PasswordEncoder enc; AuthController(UserRepository r,PasswordEncoder e){repo=r;enc=e;} @GetMapping("/login") String login(){return "login";} @PostMapping("/login") String doLogin(@RequestParam String username,@RequestParam String password){return repo.findByUsername(username).filter(u->enc.matches(password,u.getPassword())).isPresent()?"redirect:/home?user="+username:"redirect:/login?error";} @GetMapping("/register") String reg(){return "register";} @PostMapping("/register") String create(@RequestParam String username,@RequestParam String password,@RequestParam(defaultValue="") String fullName){if(repo.findByUsername(username).isPresent())return "redirect:/register?error";User u=new User();u.setUsername(username);u.setPassword(enc.encode(password));u.setFullName(fullName);repo.save(u);return "redirect:/login";} }
